import test from 'node:test';
import assert from 'node:assert/strict';
import * as sim from '../src/simulation.js';
// Published f9f2f462 engine, blob 75428c09ae5ef77cb2b03c2b354cb5623c533fee.
// Only the board import path differs. These saves are generated by the genuine
// prior engine, not by stripping a version field from a current run.
import * as prior from './fixtures/pre-recruitment-simulation.js';
import { restoreSave } from '../src/save.js';

const copy = structuredClone;
const at = (s, id) => s.cells.find(c => c.id === id);
const recruitment = s => s.events.find(e => sim.RECRUITMENT_ACTIONS.includes(e.actionId));
const contracts = s => sim.getActions(s, 'D4').filter(a => sim.RECRUITMENT_ACTIONS.includes(a.id));
const reload = s => restoreSave(JSON.parse(JSON.stringify({ state: s }))).state;
function choose(api, s, actor, cell, id) {
  const action = api.getActions(s, cell, actor).find(a => a.id === id);
  assert.ok(action, `${id} is available at ${s.year}/${cell} for ${actor}`);
  for (const evidence of action.requireEvidence) {
    if (!api.getInvestigation(s, actor, cell).evidence.includes(evidence)) api.investigate(s, actor, cell, evidence);
  }
  api.lockTask(s, actor, cell, id);
}
function submit(api, s, tasks = []) {
  for (const task of tasks) if (!s.drafts[task[0]]) choose(api, s, ...task);
  for (const actor of api.getActors(s)) if (!s.drafts[actor.id]) api.passTask(s, actor.id);
  api.commitWindow(s);
}
function decade(api, s, tasks = []) { submit(api, s, tasks); api.advanceToNextWindow(s); return s; }
function window10({ seed = 0, build = null, preserve = false } = {}, api = sim) {
  const s = api.createRun(seed);
  return decade(api, s, build ? [['protagonist', 'D4', build]] : preserve ? [['protagonist', 'B4', 'preserve_records']] : []);
}
function pending({ action = 'recruit_risk', ...options } = {}) {
  const s = window10({ build: action === 'recruit_volunteer' ? null : 'build_joint', ...options });
  submit(sim, s, [['protagonist', 'D4', action]]);
  return s;
}
function recruited(options = {}) { const s = pending(options); sim.advanceToNextWindow(s); return s; }
function assertRejected(s) {
  const before = copy(s);
  assert.equal(sim.validateState(s).valid, false);
  assert.throws(() => reload(s), /存档|招募/);
  if (s.phase === 'playback') assert.throws(() => sim.advanceYear(s), /存档|招募/);
  if (s.phase === 'planning') {
    assert.equal(sim.getWindowReview(s).ready, false);
    assert.throws(() => sim.commitWindow(s), /草稿|招募|条件/);
  }
  assert.deepEqual(s, before, 'rejection does not mutate year, costs, actors, history or snapshots');
}
function relabelPending(s, actionId, roles) {
  const event = recruitment(s);
  const origin = s.history.find(h => h.id === event.sourceActionId);
  const source = `action:10:protagonist:D4:${actionId}`;
  Object.assign(event, { actionId, id: `event:${source}`, sourceActionId: source, parentId: source, departureRoleIds: [...roles] });
  Object.assign(origin, { id: source, sourceActionId: source, departureRoleIds: [...roles] });
}

test('new recruitment version is explicit, round-trips and rejects unknown values', () => {
  const s = sim.createRun(0);
  assert.equal(s.recruitmentRulesVersion, sim.RECRUITMENT_RULES.version);
  assert.equal(sim.usesRecruitmentRules(s), true);
  assert.deepEqual(reload(s), s);
  s.recruitmentRulesVersion = 'recruitment-unknown';
  assert.equal(sim.validateState(s).valid, false);
  assert.throws(() => reload(s), /招募岗位规则版本非法/);
});

for (const preserve of [false, true]) test(`${preserve ? 'B4 records' : 'no build'}: only factual volunteer recruitment is offered`, () => {
  const s = window10({ preserve });
  const before = copy(s);
  assert.deepEqual(sim.getRecruitmentRoles(s), []);
  const choices = contracts(s);
  assert.deepEqual(choices.map(a => a.id), ['recruit_volunteer']);
  assert.deepEqual(choices[0].cost, { economy: 1 });
  assert.equal(choices[0].dueIn, 1);
  assert.equal(choices[0].probability, 1);
  assert.deepEqual(choices[0].requireEvidence, []);
  assert.match(choices[0].reward, /第11年.*第20年/);
  assert.match(choices[0].description, /没有.*岗位需要交接/);
  assert.deepEqual(s, before, 'viewing a contract spends nothing');
  for (const action of ['recruit_successor', 'recruit_risk']) {
    assert.throws(() => sim.lockTask(s, 'protagonist', 'D4', action), /不可用/);
    assert.deepEqual(s, before);
  }
  const existingInstitutions = copy(s.institutions);
  const economy = at(s, 'D4').channels.economy;
  choose(sim, s, 'protagonist', 'D4', 'recruit_volunteer');
  assert.equal(at(s, 'D4').channels.economy, economy, 'locking is not payment');
  assert.deepEqual(s.institutions, existingInstitutions);
  assert.deepEqual(sim.getActors(s).map(a => a.id), ['protagonist']);
  submit(sim, s);
  assert.equal(at(s, 'D4').channels.economy, economy - 1);
  assert.deepEqual(recruitment(s).departureRoleIds, []);
  assert.deepEqual(s.history.find(h => h.id === recruitment(s).sourceActionId).departureRoleIds, []);
  assert.equal(recruitment(s).status, 'pending');
  assert.equal(s.actors.length, 1);
  sim.advanceYear(s);
  assert.equal(s.year, 11);
  assert.equal(recruitment(s).status, 'success');
  assert.equal(recruitment(s).resolvedYear, 11);
  assert.equal(s.actors.find(a => a.id === 'linche').availableFrom, 20);
  assert.deepEqual(sim.getActors(s).map(a => a.id), ['protagonist']);
  assert.deepEqual(s.institutions, existingInstitutions, 'no carrier, trainees or succession role is awarded');
  for (const flag of ['successor', 'respected', 'trust', 'renewed']) assert.notEqual(s.flags[flag], true);
  assert.equal(sim.hasRecruitmentVacancy(s), false);
  sim.advanceToNextWindow(s);
  assert.equal(sim.getActors(s).length, 2);
  assert.equal(s.history.some(h => /-unattended$/.test(h.id)), false);
  assert.deepEqual(sim.recruitmentRolesAtDeparture(s, recruitment(s)), []);
  const refusal = sim.getActorRefusals(s, 'linche', 'D4')[0];
  assert.match(refusal.reason, /没有运转中的.*岗位需要交接/);
  assert.doesNotMatch(refusal.reason, /留下过一个岗位缺口|苏岚同意接班/);
  assert.equal(refusal.sourceEventId, recruitment(s).id);
  assert.deepEqual(reload(s), s);
});

for (const build of ['build_merchant', 'build_state', 'build_joint']) test(`${build}: a successful real station retains both succession contracts`, () => {
  const s = window10({ build, seed: build === 'build_merchant' ? 1 : 0 });
  assert.equal(s.events.find(e => e.actionId === build).status, 'success');
  assert.deepEqual(sim.getRecruitmentRoles(s).map(i => i.kind), ['station']);
  assert.deepEqual(contracts(s).map(a => a.id), ['recruit_successor', 'recruit_risk']);
  assert.deepEqual(contracts(s).map(a => a.cost), [{ economy: 5, science: 2 }, { economy: 1 }]);
  assert.deepEqual(contracts(s)[0].requireEvidence, ['successor_consent']);
});

test('failed construction leaves a real archive job with both succession choices', () => {
  const s = window10({ seed: 6, build: 'build_joint' });
  assert.equal(s.events.find(e => e.actionId === 'build_joint').status, 'failed');
  assert.deepEqual(sim.getRecruitmentRoles(s).map(i => i.kind), ['archive']);
  assert.deepEqual(contracts(s).map(a => a.id), ['recruit_successor', 'recruit_risk']);
});

for (const change of ['inactive', 'zero upkeep', 'other region']) test(`${change} carrier does not invent a D4 maintenance role`, () => {
  const s = window10({ build: 'build_joint' });
  const carrier = s.institutions.find(i => i.kind === 'station');
  if (change === 'inactive') carrier.active = false;
  if (change === 'zero upkeep') carrier.maintenance = 0;
  if (change === 'other region') carrier.cellId = 'B4';
  assert.deepEqual(sim.getRecruitmentRoles(s), []);
  assert.deepEqual(contracts(s).map(a => a.id), ['recruit_volunteer']);
});

for (const [seed, kind] of [[0, 'station'], [6, 'archive']]) {
  for (const action of ['recruit_risk', 'recruit_successor']) test(`${kind}/${action}: actual departure IDs, upkeep and historical shutdown remain factual`, () => {
    const s = window10({ seed, build: 'build_joint' });
    const carrier = s.institutions.find(i => i.cellId === 'D4' && i.kind === kind);
    const originalSource = copy(carrier.annualSource);
    submit(sim, s, [['protagonist', 'D4', action]]);
    assert.deepEqual(recruitment(s).departureRoleIds, [carrier.id]);
    sim.advanceYear(s);
    assert.equal(sim.hasRecruitmentVacancy(s), action === 'recruit_risk');
    assert.deepEqual(carrier.annualSource, originalSource, 'staffing does not rewrite the original source');
    if (kind === 'station') assert.equal(sim.getWarningCoverage(s).D4.coverage, action === 'recruit_risk' ? .5 : 1);
    while (s.year < 16) sim.advanceYear(s);
    assert.equal(carrier.active, action === 'recruit_successor');
    const shutdown = s.history.find(h => h.id === `${kind}-unattended`);
    assert.equal(!!shutdown, action === 'recruit_risk');
    if (shutdown) { assert.equal(shutdown.year, 16); assert.equal(shutdown.parentId, carrier.sourceEventId); }
    if (kind === 'station' && action === 'recruit_successor') {
      assert.equal(carrier.maintenance, .7, 'succession does not give free charter renewal');
      assert.equal(carrier.open, false);
      assert.ok(s.history.some(h => h.id === 'charter-lapsed'));
    }
    sim.advanceToNextWindow(s);
    assert.deepEqual(sim.recruitmentRolesAtDeparture(s, recruitment(s)).map(i => i.id), [carrier.id]);
    assert.deepEqual(reload(s), s, 'later shutdown does not invalidate the original role snapshot');
    assert.equal(sim.validateState(s).valid, true);
  });
}

for (const [seed, kind] of [[0, 'station'], [6, 'archive']]) test(`${kind}: later free warning preserves the real recruitment and shutdown history`, () => {
  const s = recruited({ seed });
  const departure = copy(recruitment(s));
  const shutdown = copy(s.history.find(h => h.id === `${kind}-unattended`));
  const carrier = s.institutions.find(i => i.cellId === 'D4' && i.kind === kind);
  decade(sim, s, [['protagonist', 'D4', 'free_warning']]);
  assert.deepEqual(recruitment(s), departure);
  assert.deepEqual(s.history.find(h => h.id === shutdown.id), shutdown);
  assert.equal(carrier.active, kind === 'station');
  assert.equal(sim.hasRecruitmentVacancy(s), kind === 'archive');
  if (kind === 'archive') assert.ok(s.institutions.some(i => i.cellId === 'D4' && i.kind === 'warning' && i.active));
  assert.deepEqual(reload(s), s);
});

for (const [build, action] of [[null, 'recruit_successor'], [null, 'recruit_risk'], ['build_joint', 'recruit_volunteer']]) test(`forged ${action} draft with ${build || 'no carrier'} is rejected atomically`, () => {
  const s = window10({ build });
  s.drafts.protagonist = { actorId: 'protagonist', cellId: 'D4', actionId: action, evidence: [], status: 'locked', window: 10 };
  assertRejected(s);
});

const pendingMutations = [
  ['missing event source', (s,e) => { delete e.sourceActionId; }],
  ['null event source', (s,e) => { e.sourceActionId = null; }],
  ['wrong event parent', (s,e) => { e.parentId = 'arrival'; }],
  ['wrong event ID', (s,e) => { e.id = 'event:invented'; }],
  ['invented executor', (s,e,h) => { const source=e.sourceActionId.replace(':protagonist:',':linche:'); e.id=`event:${source}`;e.parentId=source;e.sourceActionId=source;h.id=source;h.sourceActionId=source; }],
  ['missing action history', (s,e,h) => { s.history = s.history.filter(x => x !== h); }],
  ['wrong source history year', (s,e,h) => { h.year = 0; }],
  ['wrong source history region', (s,e,h) => { h.cellId = 'B4'; }],
  ['missing role snapshot', (s,e) => { delete e.departureRoleIds; }],
  ['wrong snapshot type', (s,e) => { e.departureRoleIds = 'station'; }],
  ['mismatched action snapshot', (s,e,h) => { h.departureRoleIds = []; }],
  ['missing action snapshot', (s,e,h) => { delete h.departureRoleIds; }],
  ['invented role ID', (s,e,h) => { e.departureRoleIds = ['institution:invented']; h.departureRoleIds = [...e.departureRoleIds]; }],
  ['actor ID used as role', (s,e,h) => { e.departureRoleIds = ['linche']; h.departureRoleIds = [...e.departureRoleIds]; }],
  ['remote training used as role', (s,e,h) => { e.departureRoleIds = [s.institutions.find(i=>i.kind==='training').id]; h.departureRoleIds=[...e.departureRoleIds]; }],
  ['duplicated role ID', (s,e,h) => { e.departureRoleIds.push(e.departureRoleIds[0]); h.departureRoleIds = [...e.departureRoleIds]; }],
  ['wrong scheduled year', (s,e) => { e.year = 12; }],
];
for (const [label, mutate] of pendingMutations) test(`pending recruitment rejects ${label} before any write`, () => {
  const s = pending(); const e = recruitment(s); const h = s.history.find(h => h.id === e.sourceActionId);
  mutate(s,e,h); assertRejected(s);
});

