for (const action of sim.RECRUITMENT_ACTIONS) for (const [label, change] of [
  ['missing', e => { delete e.resolvedYear; }], ['different', e => { e.resolvedYear=12; }],
  ['string', e => { e.resolvedYear='11'; }], ['zero', e => { e.resolvedYear=0; }],
]) test(`${action} rejects ${label} completion date and never invents a dated commitment`, () => {
  const s = recruited({ action }); change(recruitment(s)); assertRejected(s);
  assert.equal(sim.fulfilledEvent(s, sim.RECRUITMENT_ACTIONS), null);
  const refusal = sim.getActorRefusals(s, 'linche', 'D4')[0];
  assert.equal(refusal.sourceEventId, null);
  assert.match(refusal.reason, /缺少可核实/);
  assert.doesNotMatch(refusal.reason, /undefined|第11年|第12年/);
});
for (const action of sim.RECRUITMENT_ACTIONS) for (const [label, change] of [
  ['failed event', (s,e) => { e.status='failed'; }],
  ['missing outcome history', (s,e) => { s.history=s.history.filter(h=>h.id!==`resolved:${e.id}`); }],
  ['mismatched outcome source', (s,e) => { s.history.find(h=>h.id===`resolved:${e.id}`).sourceActionId='other'; }],
  ['mismatched outcome year', (s,e) => { s.history.find(h=>h.id===`resolved:${e.id}`).year=12; }],
]) test(`${action}: ${label} is not proof of a personal promise`, () => {
  const s = recruited({ action }); change(s,recruitment(s)); const before=copy(s);
  assert.equal(sim.fulfilledEvent(s, sim.RECRUITMENT_ACTIONS), null);
  assert.equal(sim.getActorRefusals(s, 'linche', 'D4')[0].sourceEventId, null);
  assert.deepEqual(s, before);
});

const oldRoutes = [
  { name: 'no job, risky recruitment', action: 'recruit_risk' },
  { name: 'no job, costly successor recruitment', action: 'recruit_successor' },
  { name: 'B4 records, risky recruitment', action: 'recruit_risk', preserve: true },
  { name: 'failed-build archive, risky recruitment', action: 'recruit_risk', build: 'build_joint', seed: 6 },
  { name: 'working station, successor recruitment', action: 'recruit_successor', build: 'build_joint' },
  { name: 'working station, risky recruitment', action: 'recruit_risk', build: 'build_joint' },
];
function oldTasks(s, route) {
  if (s.year === 10) return [['protagonist','D4',route.action]];
  if (s.year === 20) return [['protagonist','D4','free_warning'],['linche','B4','local_veto']];
  if (s.year === 30) return [['protagonist','D4','withdraw'],['linche','D5','mutual_aid']];
  return [];
}
for (const route of oldRoutes) for (const stage of ['planning','locked','submitted','resolved','ended']) test(`genuine f9f2f462 ${route.name}, ${stage}: exact yearly continuation and ending survive`, () => {
  const old = window10(route, prior);
  assert.equal(Object.hasOwn(old, 'recruitmentRulesVersion'), false);
  assert.equal(old.aftermathRulesVersion, sim.AFTERMATH_RULES.version, 'aftermath is not a proxy for the new contract');
  if (stage !== 'planning') choose(prior, old, 'protagonist','D4',route.action);
  if (['submitted','resolved','ended'].includes(stage)) submit(prior, old);
  if (['resolved','ended'].includes(stage)) prior.advanceYear(old);
  if (stage === 'ended') while (old.year < 40) {
    if (old.phase === 'planning') submit(prior, old, oldTasks(old,route));
    prior.advanceYear(old);
  }
  const untouched = copy(old);
  const loaded = reload(old);
  assert.deepEqual(old, untouched, 'loading leaves the input untouched');
  assert.deepEqual(loaded, old);
  assert.equal(sim.usesRecruitmentRules(loaded), false);
  if (loaded.year === 10 && loaded.phase === 'planning') {
    assert.deepEqual(contracts(loaded).map(a=>a.id), ['recruit_successor','recruit_risk']);
    for (const action of ['recruit_successor','recruit_risk']) {
      assert.deepEqual(sim.getActions(loaded,'D4').find(a=>a.id===action), prior.getActions(old,'D4').find(a=>a.id===action));
    }
  }
  while (old.year < 40) {
    if (old.phase === 'planning') {
      submit(prior, old, oldTasks(old,route));
      submit(sim, loaded, oldTasks(loaded,route));
      assert.deepEqual(loaded, old, `submission at year${old.year} preserves all contracts`);
    }
    prior.advanceYear(old); sim.advanceYear(loaded);
    assert.deepEqual(loaded, old, `year${old.year}: cells, sources, actors, flags, snapshots and history`);
    assert.deepEqual(sim.getEnding(loaded), prior.getEnding(old), `year${old.year}: existing ending output is unchanged`);
  }
  assert.equal(sim.validateState(loaded).valid, true);
  assert.deepEqual(loaded, old);
  assert.deepEqual(sim.getEnding(loaded), prior.getEnding(old));
  assert.deepEqual(reload(loaded), loaded);
});

test('new no-job recruitment does not add a hidden penalty to the previous low-cost no-build route', () => {
  const current = window10({ preserve: true });
  const old = window10({ preserve: true }, prior);
  submit(sim, current, [['protagonist','D4','recruit_volunteer']]);
  submit(prior, old, [['protagonist','D4','recruit_risk']]);
  while (current.year < 40) {
    if (current.phase === 'planning') {
      const tasks = current.year === 20
        ? [['protagonist','B4','local_veto'], ['linche','E4','train_network']]
        : [['protagonist','D4','withdraw'], ['linche','D5','mutual_aid']];
      submit(sim, current, tasks); submit(prior, old, tasks);
    }
    sim.advanceYear(current); prior.advanceYear(old);
    assert.deepEqual(current.cells, old.cells, `year${current.year}: no additional channel penalty`);
    assert.deepEqual(current.snapshots, old.snapshots, `year${current.year}: all earlier board states remain equal`);
    assert.deepEqual(current.institutions, old.institutions, `year${current.year}: no free or removed carrier`);
    assert.deepEqual(current.flags.crisis, old.flags.crisis);
    assert.deepEqual(sim.getEnding(current), prior.getEnding(old), `year${current.year}: no invented reward or scoring penalty`);
  }
  assert.equal(sim.getEnding(current).title, '没有唯一守夜人');
  assert.equal(current.history.some(h => /-unattended$/.test(h.id)), false);
  assert.equal(sim.validateState(current).valid, true);
});


